{
  "repository": "Aliuyanfeng/dsh-soul",
  "revision": "0a203cc24e39beea3d3c8cc00541b4709e87c49f",
  "component": "",
  "inspected_paths": [
    "README.md",
    "package.json",
    "index.mjs"
  ],
  "research_questions": {
    "goal": "确认 dsh-soul 在固定版本中实际实现了什么、相对基线的贡献与关键限制，并给出有证据边界的采用和未来验证结论。",
    "questions": [
      {
        "id": "Q01",
        "topics": [
          "scenario"
        ],
        "question": "目标用户、反复任务、原有办法与合格结果是什么？",
        "status": "answered",
        "answer": "目标用户是需要在不同项目或会话中稳定切换角色提示和个性设置的用户。反复任务是管理人格配置并按全局、工作区或会话范围绑定，在提示装配时注入且提供命令、工具和界面入口。原有办法为手工维护系统提示并在每个会话复制，或只使用宿主全局设置。合格结果必须达到“当前人格和作用域可见、变更即时且可撤销，不在错误项目泄漏提示或历史”，不能以安装成功、工具注册或一次演示替代。",
        "evidence": [
          {
            "kind": "author_claim",
            "source_path": "README.md",
            "line_start": 1,
            "line_end": 19,
            "observation": "作者材料限定目标任务和操作入口；研究回答另加合格交付标准。"
          }
        ],
        "unknowns": []
      },
      {
        "id": "Q02",
        "topics": [
          "mechanism"
        ],
        "question": "入口、调用链、数据和状态如何实现核心能力？",
        "status": "answered",
        "answer": "index.mjs 中的固定片段显示关键入口、注册或生命周期接线，包清单限定加载组件。实际链路围绕“创建/选择persona并预览最终提示差异｜内容与来源明确，不含不应跨项目的秘密；绑定全局、工作区或会话并检查优先级｜界面与实际装配结果一致；切换/撤销后新旧会话分别核对｜历史可回滚，其他工作区不受影响”推进，状态发生在插件配置、宿主服务或外部目标中。静态路径只能证明机制存在，不能证明注册后所有分支可运行。",
        "evidence": [
          {
            "kind": "source_inspection",
            "source_path": "index.mjs",
            "line_start": 462,
            "line_end": 479,
            "observation": "关键源码片段支持入口、注册或生命周期接线。"
          },
          {
            "kind": "author_claim",
            "source_path": "package.json",
            "line_start": 1,
            "line_end": 26,
            "observation": "包清单绑定版本、入口和宿主声明。"
          }
        ],
        "unknowns": []
      },
      {
        "id": "Q03",
        "topics": [
          "contribution"
        ],
        "question": "相比宿主原生能力和简单替代，具体增量与归属是什么？",
        "status": "answered",
        "answer": "研究者识别的增量是把人格存储、范围继承、历史、命令/工具与多处 UI 接线组合为可管理的个性化层。参照是“手工维护系统提示并在每个会话复制，或只使用宿主全局设置”。贡献归属于本插件的集成、状态编排或工作流封装，不把外部服务、上游算法或子组件能力重复算作原创，也不从功能数量推断用户收益。",
        "evidence": [
          {
            "kind": "source_inspection",
            "source_path": "index.mjs",
            "line_start": 462,
            "line_end": 479,
            "observation": "源码证明本插件承担接线或编排，而非仅有文字描述。"
          },
          {
            "kind": "author_claim",
            "source_path": "README.md",
            "line_start": 1,
            "line_end": 19,
            "observation": "README 提供作者主张，用于与源码可见机制分开比较。"
          }
        ],
        "unknowns": []
      },
      {
        "id": "Q04",
        "topics": [
          "limitations"
        ],
        "question": "什么前提最可能使核心贡献无法转化为端到端价值？",
        "status": "partial",
        "answer": "最有力支持是固定源码确有相应接线；最关键反例或其他解释是多级作用域和兼容接线增加状态复杂度；源码测试不能证明所有宿主版本的实时提示更新和隔离都正确。若失败后不能判断副作用是否已发生，局部自动化可能把恢复负担转移给用户。该问题不直接否定插件，但会把适用范围收窄到可隔离、可回读的任务。",
        "evidence": [
          {
            "kind": "source_inspection",
            "source_path": "index.mjs",
            "line_start": 462,
            "line_end": 479,
            "observation": "源码显示关键状态边界，也说明为什么需要运行时故障验证。"
          }
        ],
        "unknowns": [
          {
            "issue": "缺少针对“多级作用域和兼容接线增加状态复杂度；源码测试不能证明所有宿主版本的实时提示更新和隔离都正确”的固定版本故障注入记录",
            "impact": "无法确认核心贡献在异常路径仍成立",
            "next_step": "建立3个人格×3个工作区×新旧会话矩阵，连续切换并重启；比较最终提示来源、跨项目泄漏、撤销成功数和额外token，任何秘密跨工作区出现即停止。 本题重点观察异常是否改变贡献结论。",
            "kind": "research_gap"
          }
        ]
      },
      {
        "id": "Q05",
        "topics": [
          "dependencies"
        ],
        "question": "启动、持续生效和失败恢复各依赖什么，操作负担由谁承担？",
        "status": "partial",
        "answer": "关键依赖分别是：DSH prompt/agent/working-directory 与客户端槽位｜必需｜解析作用域并注入人格/显示UI｜接口不兼容时禁用对应入口；人格配置、历史与作用域存储｜必需｜保存persona及全局/工作区/会话绑定｜损坏时回到默认且保留备份；命令 soul 与 set_persona 工具权限｜切换时必需｜允许用户或Agent改变人格｜未授权Agent不得跨作用域写入。启动者负责版本与权限，使用者负责输入和验收，维护者负责外部服务/API 漂移。失败恢复按“切换/撤销后新旧会话分别核对｜历史可回滚，其他工作区不受影响”执行；包依赖存在或工具可注册都不表示业务已经办结。",
        "evidence": [
          {
            "kind": "author_claim",
            "source_path": "package.json",
            "line_start": 1,
            "line_end": 26,
            "observation": "包清单提供运行时、依赖和分发边界。"
          },
          {
            "kind": "source_inspection",
            "source_path": "index.mjs",
            "line_start": 462,
            "line_end": 479,
            "observation": "源码提供实际宿主接线，用于区分声明依赖与调用依赖。"
          }
        ],
        "unknowns": [
          {
            "issue": "真实宿主中的依赖失效顺序与部分成功状态未观测",
            "impact": "无法确认重试是否会重复副作用",
            "next_step": "建立3个人格×3个工作区×新旧会话矩阵，连续切换并重启；比较最终提示来源、跨项目泄漏、撤销成功数和额外token，任何秘密跨工作区出现即停止。 另逐项切断依赖并回读部分成功状态。",
            "kind": "research_gap"
          }
        ]
      },
      {
        "id": "Q06",
        "topics": [
          "cost"
        ],
        "question": "完成一个合格任务的首次、持续和失败恢复成本与效果是什么？",
        "status": "partial",
        "answer": "成本必须以“当前人格和作用域可见、变更即时且可撤销，不在错误项目泄漏提示或历史”为合格单位。三阶段投入为：首次使用｜本地配置/素材存储｜设计人格、审阅提示和作用域规则｜建立persona所需小时未知；持续使用｜提示token与客户端状态维护｜切换、检查覆盖来源和处理宿主升级｜每轮额外token与误绑率未知；失败恢复｜历史/存储回放资源｜恢复旧persona、清除错误绑定并重建装配｜错误人格已影响输出需人工审计。当前源码只支持机制存在，效果维度为“多作用域人格｜store/bindings/session/workspace模块存在｜优先级在所有宿主版本的一致性；实时提示更新｜注入与domain/changed接线存在｜在进行中会话的生效时点；可管理界面｜命令、工具和多个UI槽位存在｜入口间状态漂移与撤销可靠性”。没有合格数、总尝试、人工分钟与现金/资源量，因此不能计算单位成本、节时或ROI。",
        "evidence": [
          {
            "kind": "author_claim",
            "source_path": "README.md",
            "line_start": 1,
            "line_end": 19,
            "observation": "作者材料支持操作范围，不提供同条件成本或合格率。"
          },
          {
            "kind": "author_claim",
            "source_path": "package.json",
            "line_start": 1,
            "line_end": 26,
            "observation": "包清单支持本地/外部资源与依赖边界的定性判断。"
          }
        ],
        "unknowns": [
          {
            "issue": "缺少按合格任务统计的总尝试、失败、人工分钟与现金/资源量",
            "impact": "无法比较总成本与净收益",
            "next_step": "建立3个人格×3个工作区×新旧会话矩阵，连续切换并重启；比较最终提示来源、跨项目泄漏、撤销成功数和额外token，任何秘密跨工作区出现即停止。 同时按合格交付数汇总总尝试、人工分钟和资源量。",
            "kind": "research_gap"
          }
        ]
      },
      {
        "id": "Q07",
        "topics": [
          "engineering"
        ],
        "question": "实现是否可靠可维护，哪些设计可复用，移植代价是什么？",
        "status": "partial",
        "answer": "固定源码把核心职责落在 index.mjs 及相邻模块，入口可追踪；inventory 仅作规模和静态候选索引。可复用的是“把人格存储、范围继承、历史、命令/工具与多处 UI 接线组合为可管理的个性化层”的显式接线方式。移植必须重做宿主API、权限、状态持久化和“切换/撤销后新旧会话分别核对｜历史可回滚，其他工作区不受影响”验证，不能从测试脚本存在推断当前环境可靠。",
        "evidence": [
          {
            "kind": "source_inspection",
            "source_path": "index.mjs",
            "line_start": 462,
            "line_end": 479,
            "observation": "固定源码用于评价职责和宿主耦合。"
          },
          {
            "kind": "author_claim",
            "source_path": "package.json",
            "line_start": 1,
            "line_end": 26,
            "observation": "包清单用于确认版本、分发与依赖面。"
          }
        ],
        "unknowns": [
          {
            "issue": "未执行仓库测试、安装和真实宿主压力/升级验证",
            "impact": "维护性和异常恢复只能作源码级判断",
            "next_step": "建立3个人格×3个工作区×新旧会话矩阵，连续切换并重启；比较最终提示来源、跨项目泄漏、撤销成功数和额外token，任何秘密跨工作区出现即停止。 在此之外记录构建、卸载和宿主升级后的回归面积。",
            "kind": "research_gap"
          }
        ]
      },
      {
        "id": "Q08",
        "topics": [
          "hypothesis"
        ],
        "question": "由贡献与反例可推导什么未验证方向，如何证伪？",
        "status": "partial",
        "answer": "由“把人格存储、范围继承、历史、命令/工具与多处 UI 接线组合为可管理的个性化层”和“多级作用域和兼容接线增加状态复杂度；源码测试不能证明所有宿主版本的实时提示更新和隔离都正确”推导的新方向是可用显式优先级图展示每次提示的来源与覆盖关系，并为人格切换提供可回放的差异和撤销事务。它不是当前能力。最小验证为建立3个人格×3个工作区×新旧会话矩阵，连续切换并重启；比较最终提示来源、跨项目泄漏、撤销成功数和额外token，任何秘密跨工作区出现即停止。 若合格结果不改善、误差/副作用越界或恢复负担高于“手工维护系统提示并在每个会话复制，或只使用宿主全局设置”，即削弱或推翻假设。",
        "evidence": [
          {
            "kind": "source_inspection",
            "source_path": "index.mjs",
            "line_start": 462,
            "line_end": 479,
            "observation": "假设只以已实现机制和边界为推导起点，不表示源码已经实现新方向。"
          }
        ],
        "unknowns": [
          {
            "issue": "假设尚无实现、需求频率或效果数据",
            "impact": "不能计入插件贡献、创新效果或商业机会",
            "next_step": "建立3个人格×3个工作区×新旧会话矩阵，连续切换并重启；比较最终提示来源、跨项目泄漏、撤销成功数和额外token，任何秘密跨工作区出现即停止。 只验证最小原型，不改变当前能力状态。",
            "kind": "research_gap"
          }
        ]
      },
      {
        "id": "Q09",
        "topics": [
          "adoption"
        ],
        "question": "对谁值得观察或试用，成功与停止标准是什么？",
        "status": "partial",
        "answer": "当前结论为小范围试用。频繁切换项目角色者可在非敏感工作区试用，先验证作用域优先级、撤销和跨会话隔离。 试用成功标准是“当前人格和作用域可见、变更即时且可撤销，不在错误项目泄漏提示或历史”，并且 优先级在所有宿主版本的一致性、在进行中会话的生效时点、入口间状态漂移与撤销可靠性 有可接受结果；停止标准包括发生多级作用域和兼容接线增加状态复杂度；源码测试不能证明所有宿主版本的实时提示更新和隔离都正确所述核心风险、出现未知副作用自动重试，或总人工/资源成本高于“手工维护系统提示并在每个会话复制，或只使用宿主全局设置”。",
        "evidence": [
          {
            "kind": "author_claim",
            "source_path": "README.md",
            "line_start": 1,
            "line_end": 19,
            "observation": "作者材料限定可操作范围；采用结论由研究者结合限制给出。"
          },
          {
            "kind": "source_inspection",
            "source_path": "index.mjs",
            "line_start": 462,
            "line_end": 479,
            "observation": "源码证据只支撑窄范围试用/观察，不构成安装验收。"
          }
        ],
        "unknowns": [
          {
            "issue": "未有真实用户频率、迁移意愿与固定版本宿主验收",
            "impact": "不能升级为持续安装或生产采用",
            "next_step": "建立3个人格×3个工作区×新旧会话矩阵，连续切换并重启；比较最终提示来源、跨项目泄漏、撤销成功数和额外token，任何秘密跨工作区出现即停止。 试用结束还需访谈目标用户的重复频率与退出意愿。",
            "kind": "research_gap"
          }
        ]
      }
    ]
  },
  "files": [
    {
      "path": "README.md",
      "content": "# dsh-soul\n\n[简体中文](./README.md) | [English](./README_EN.md)\n\n[![Listed on dsh-plugin.org](https://dsh-plugin.org/badges/listed.svg)](https://dsh-plugin.org/plugins/aliuyanfeng/dsh-soul)\n[![XERJ Corpus Hub contributor](https://hub.xerj.org/contributors/Aliuyanfeng/badge.svg)](https://hub.xerj.org/contributors/Aliuyanfeng)\n[![License: MIT](https://img.shields.io/badge/License-MIT-yellow.svg)](./LICENSE)\n[![GitHub stars](https://img.shields.io/github/stars/Aliuyanfeng/dsh-soul?style=social)](https://github.com/Aliuyanfeng/dsh-soul/stargazers)\n[![GitHub issues](https://img.shields.io/github/issues/Aliuyanfeng/dsh-soul)](https://github.com/Aliuyanfeng/dsh-soul/issues)\n[![GitHub last commit](https://img.shields.io/github/last-commit/Aliuyanfeng/dsh-soul)](https://github.com/Aliuyanfeng/dsh-soul/commits)\n[![GitHub repo size](https://img.shields.io/github/repo-size/Aliuyanfeng/dsh-soul)](https://github.com/Aliuyanfeng/dsh-soul)\n[![Verify](https://github.com/Aliuyanfeng/dsh-soul/actions/workflows/ci.yml/badge.svg)](https://github.com/Aliuyanfeng/dsh-soul/actions/workflows/ci.yml)\n[![npm version](https://img.shields.io/npm/v/dsh-soul)](https://www.npmjs.com/package/dsh-soul)\n[![npm downloads](https://img.shields.io/npm/dm/dsh-soul)](https://www.npmjs.com/package/dsh-soul)\n\nDeepSeek Harness 个性化设置插件，用于配置 Agent 的昵称、回复风格、语调和自定义指令。\n\n## 功能\n\n- Web UI 个性化设置页面\n- 设置页体验：中英双语文案（随界面语言切换）、dirty 检测（无改动禁用保存）、保存结果提示、提示词预览只读面板\n- 启用或禁用个性化设置\n- 「关于你」：设置用户昵称、职业和介绍，回复时结合你的背景\n- 选择回复风格和语调（合并为单一选项）：`professional`（专业严谨）、`casual`（轻松自然）、`humorous`（幽默风趣）、`roast`（吐槽达人）、`efficient`（高效干练）\n- 特质微调（在风格和语调的基础上叠加）：\n  - 标题和列表：`default`（默认）、`more`（增强，采用清晰格式和列表结构）、`less`（减弱，使用更多段落文本）\n  - 表情符号：`default`（默认）、`more`（增强，使用较多表情符号）、`less`（减弱，尽量减少使用表情符号）\n  - 表格：`default`（默认）、`more`（增强，呈现对比或多字段信息时优先使用表格）、`less`（减弱，避免表格、改用列表或段落）\n- 回复长度偏好：`concise`（简洁，只讲要点、不展开）、`normal`（适中，不额外约束，默认）、`detailed`（详尽，充分展开背景、步骤与推理）\n- 选择输出语言（Agent 回复语言 + `/soul` 命令输出语言）：中文 / English\n- 提示词随输出语言本地化：`language=en` 时 system prompt 使用英文描述\n- 输入自定义指令\n- Agent 可调用工具 `set_persona`，让模型在对话中直接调整人设\n- 人设预设：7 个内置人设（苏格拉底式提问者 / 极简主义者 / 资深架构师 / 教学型讲解者 / 严格代码审阅者 / 头脑风暴伙伴 / 自驱型协作者，随插件提供、不可删除）+ 多套自建人设一键切换（保存 / 使用 / 列表 / 删除，Web UI 与命令双入口）；每行摘要显示风格与偏离默认的维度\n- 预设只管 Agent 的人格：**切换预设不会动「关于你」**（昵称 / 职业 / 介绍是你本人的资料，与「Agent 怎么说话」是两码事）。内置与自建一视同仁——保存预设时只快照风格 / 特质 / 回复长度 / 输出语言 / 自定义指令，不包含身份字段；早期版本存下的完整快照会在读取时自动剥离\n- `set_persona` 确认模式（`requireToolConfirmation`）：Agent 的人设修改先在输入框处弹出**宿主原生审批面板**，由你点「允许一次」或「拒绝」（`Enter` 允许 / `Esc` 拒绝）后才会生效；审批通道不可用时（如会话审批策略为 `never`）退化为待确认提议，需 `/soul confirm` 处理\n- 输入框光轨：Agent 回复中时，输入框边框显示沿边循环流动的光轨（默认颜色 `#679EFE`）\n  - 颜色：预设色板、取色器或十六进制输入（如 `#679EFE`）\n  - 流动速度：慢 / 中 / 快；光带粗细：细 / 中 / 粗\n  - 光轨起点、终点沿边框匀速推进，带渐隐拖尾；与输入框边框完全重合，不出现双线\n  - 设置页内置实时效果示例，随颜色 / 速度 / 粗细联动；系统开启「减少动态效果」时自动停用\n- `/soul set` 键值方式修改配置项\n- 配置持久化保存\n- 配置输入校验：字段白名单、类型、长度上限（昵称/职业 50、介绍 500、自定义指令 2000 字符）、枚举与十六进制颜色校验，非法或超限字段整单拒绝\n- 配置持久化健壮性：写入为**原子替换**（先写临时文件再 `rename`，中断不会留下半份配置）；读取区分「文件不存在」与「文件损坏」——损坏时保留原文件、另存 `.corrupt` 备份、**拒绝覆写**，并把原因直接显示在设置页，避免自定义指令与人设库被静默清空\n- 配置损坏时有**逃生口**：「重置」会先把损坏文件移开（备份为 `.corrupt`）再写入默认值 —— 否则损坏状态下五条写路径全被拒，用户只能自己删文件\n- 送达可观测：`/soul show` 的「送达」行、`GET /api/soul/status`、设置页提示条（`configError` = 配置读不出来；`deliveryWarning` = 配置送不到活动会话）\n- 提示词插值已关闭：自定义指令里的 `{{…}}` 按字面保留，不会触发宿主提示词装配失败\n- 配置更新后同步到所有活动 Agent\n- 变更检测：仅在影响 Agent 行为的配置实际变化时刷新提示词并注入会话；纯外观配置（输入框光轨）只落盘，不产生注入消息\n- 变更记录与回滚（**插件详情页**：插件管理 → 已安装插件 → dsh-soul；设置页只在「人设预设」展开区给出指引，保留条数下拉也在这个区块内）：每次配置改动都追加一条记录（时间、**来源**、字段级 `原值 → 新值`），可**撤销某一次改动及其之后的全部改动**；删掉的预设可单点恢复。记录写在 `$DSH_HOME/soul-config.history.jsonl`（追加式，一行一条，人能直接读），保留条数可调（50 / 100 / 200 / 500，默认 200，改完即时生效）；存不下时**只影响记录、不影响配置写入**，并如实告诉你「记录可能不完整」。详情页给时间线与撤销，也可直接看文件\n- 插件图标：插件管理列表与侧栏入口显示专属图标（`assets/icon.svg`，36×36，随 npm 包发布）\n- 设置导航图标：设置面板左侧「个性化」那一项显示与插件图标同一套几何的图标——同一条光轨与火花，颜色与线宽则跟随邻居（单色 `currentColor`）；DSH 的导航图标按 section id 硬编码、插件声明不了，故由客户端做 DOM 替换\n- 提示词预览（只读，设置页底部折叠区）：无未保存编辑时显示**当前生效**的提示词；表单一有改动就转为预览**草稿**——展示保存后真正会注入的内容，边改边看（停止输入 400ms 后自动重新编译），并在保存 / 重置 / 应用预设后自动刷新。未通过校验的字段会单独列出且不计入预览\n\n## 路线图\n\n| 版本 | 方向 | 状态 |\n| --- | --- | --- |\n| `0.7.2` | 设置页样式对齐宿主、卡片堆叠轮播、人设变更走宿主原生审批面板 | 已发布 |\n| `0.8.0` | **变更审计与回滚** —— 记录每次配置改动（时间戳、来源、字段级 from→to），插件详情页给时间线与撤销 | 已发布 |\n| `0.9.0` | **三级配置作用域** —— Global → Workspace → Session：工作区决定人设、会话可临时覆盖，附保守回收 | 已发布 |\n| `0.10.0` | 自演化提议 + diff 审批 —— Agent 提议精炼人设，改动以 diff 走审批面板 | 规划中 |\n| `0.11.0` | 记忆层 —— 跨会话长期记忆，按人设隔离、按需召回 | 规划中 |\n\n设计与取舍写在 `docs/` 下的设计文档里；已发布的改动见 [RELEASE_NOTES.md](./RELEASE_NOTES.md)，发版流程见 [PUBLISHING.md](./PUBLISHING.md)，排查手册见 [DEBUGGING.md](./DEBUGGING.md)。路线图是方向而非承诺，顺序可能调整。\n\n### 文档\n\n| 文件 | 内容 |\n| --- | --- |\n| [README.md](./README.md) / [README_EN.md](./README_EN.md) | 功能、安装、使用（面向使用者） |\n| [RELEASE_NOTES.md](./RELEASE_NOTES.md) | 每个版本的详细变更记录（面向排查与追溯） |\n| [DEBUGGING.md](./DEBUGGING.md) | 现象 → 原因的排查手册、校验链构成 |\n| [PUBLISHING.md](./PUBLISHING.md) | 发版流程与 npm 发布配置 |\n| [QUICK_START.md](./QUICK_START.md) | 最短上手路径 |\n| [docs/DESIGN-config-scope.md](./docs/DESIGN-config-scope.md) | 三级作用域：为什么这样分层、回收为什么保守 |\n| [docs/DESIGN-audit-rollback.md](./docs/DESIGN-audit-rollback.md) | 变更审计：撤销语义为什么是\"连同之后的改动\" |\n| [docs/DESIGN-persona-scope.md](./docs/DESIGN-persona-scope.md) | 按目录绑定的原始设计（0.9.0 的前身，路径规范化部分仍在使用） |\n\n## 安装\n\n```powershell\ndsh plugin --profile <profile> add dsh-soul\ndsh plugin --profile <profile> update dsh-soul\n```\n\n插件配置由 `cordis.patch.yml` 提供：\n\n```yaml\n- insert:\n    - id: soul\n      name: dsh-soul\n```\n\n## 兼容性\n\n插件不打包 DSH 运行时包，全部由宿主提供。DSH 会在装载前校验 `peerDependencies`，**比较对象是 DSH 运行时版本**（`@deepseek-ai/dsh-app-boot` 的 version），而不是这些包各自的版本：\n\n| 包 | 范围 |\n| --- | --- |\n| `@deepseek-ai/dsh-llm` | `>=0.1.1-rc.2 <0.3.0-0` |\n| `@deepseek-ai/dsh-tools` | `>=0.1.0-rc.6 <0.3.0-0` |\n| `@deepseek-ai/cordis` | `^4.0.1 \\|\\| ^4.0.5-alpha.1` |\n\n即支持 DSH **0.1.x 与 0.2.x**（含 prerelease 版本）。可用 `npm run verify:compat` 在当前环境确认声明是否成立。\n\n若 DSH 提示「dsh-soul@x.y.z 与 DSH a.b.c 不兼容」，说明插件版本早于该 DSH 版本，升级插件即可：\n\n```powershell\ndsh plugin --profile <profile> update dsh-soul\n```\n\n## 截图\n\n**设置页（关于你 + 特质）**\n\n![设置页上半部分：关于你 与 特质起始](./screenshots/image0.png)\n\n**设置页（特质 + 输出语言 + 自定义指令）**\n\n![设置页下半部分：特质、输出语言与自定义指令](./screenshots/image1.png)\n\n**`/soul` 命令提示**\n\n![`/soul` 命令自动补全提示与输入框](./screenshots/image2.png)\n\n**`/soul` 命令输出（设置昵称、show、enable、disable、reset）**\n\n![`/soul` 多种命令的输出示例](./screenshots/image3.png)\n\n## 使用\n\n启动 DSH 后，进入设置页面中的「个性化设置」栏目，修改配置并点击「保存设置」。\n\n也可以使用斜杠命令：\n\n```text\n/soul show        查看当前配置（含确认模式、预设数量与送达状态）\n/soul set k=v     修改配置项（如 /soul set style=humorous language=en；光轨：trailColor=#679EFE trailSpeed=fast trailWidth=thick）\n/soul save <名>   保存当前人设为预设（只含人格维度，不含「关于你」；内置名不可占用）\n/soul use <名>    应用人设预设（内置预设同样可用）\n/soul list        查看人设预设（✔ 标记当前匹配项；内置项带 [内置] 标记）\n/soul del <名>    删除人设预设（delete / rm 别名；内置预设不可删）\n/soul confirm     应用待确认的人设变更（确认模式）\n/soul reject      拒绝待确认的人设变更\n/soul reset       重置配置（保留人设预设库）；配置损坏时这是逃生口，会先备份为 .corrupt\n/soul enable      启用个性化设置\n/soul disable     禁用个性化设置\n/soul 小明        设置昵称\n```\n\n配置保存后会同步到所有活动 Agent，当前会话下一次请求即可使用最新配置；无实际变化的保存不产生注入消息。\n\nAgent 也可以通过工具 `set_persona` 在对话中直接调整你的人设（昵称、回复风格和语调、特质、回复语言、自定义指令）。模型只会在明确请求改变称呼、语气、风格或语言时调用该工具。开启「人设变更需确认」（`requireToolConfirmation`）后，该工具的修改会先在输入框处弹出**宿主原生审批面板**（与沙箱提权、模型切换用的是同一套交互），由你点「允许一次」或「拒绝」——`Enter` 允许、`Esc` 拒绝，改动会写入会话审计日志。审批通道不可用时（例如会话审批策略为 `never`、或没有可用的 Web UI 应答者）则退化为待确认提议，需 `/soul confirm` 确认或 `/soul reject` 拒绝。若你处在完全权限的会话中（审批策略 `never`），面板不会出现、每次变更都要手动输入命令，此时建议关闭该开关。\n\n## 配置文件\n\n插件将配置保存到 DSH 的用户数据目录，文件名为：\n\n```text\nsoul-config.json\n```\n\n配置示例：\n\n```json\n{\n  \"enabled\": true,\n  \"nickname\": \"小明\",\n  \"occupation\": \"软件工程师\",\n  \"bio\": \"对编程和技术感兴趣\",\n  \"style\": \"professional\",\n  \"language\": \"zh\",\n  \"customInstructions\": \"请保持简洁，优先给出结论。\",\n  \"requireToolConfirmation\": false,\n  \"trailEnabled\": true,\n  \"trailColor\": \"#679EFE\",\n  \"trailSpeed\": \"slow\",\n  \"trailWidth\": \"thin\"\n}\n```\n\n自建人设预设保存在同一文件的 `personas` 字段：名称 → 人设字段快照（风格 / 特质 / 回复长度 / 输出语言 / 自定义指令）+ `updatedAt`。**预设不含「关于你」**（昵称 / 职业 / 介绍）——那是使用者本人的资料，切换预设只换 Agent 的说话方式；这条由 `PROFILE_FIELDS` 与 `PERSONA_FIELDS`（`lib/config.mjs`）结构性保证：保存快照、应用取键、★ 匹配判据、磁盘归一化四条路径都按 `PERSONA_FIELDS` 白名单走，所以内置与自建行为一致。预设库变更不影响活动配置，使用预设时才应用到配置并同步会话。内置人设不落盘（见 `lib/personas.mjs`），列表 / 使用 / ★ 匹配统一走「内置 + 自建」的合并视图，同名以内置为准，内置名既不可保存占用也不可删除。\n\n输入框光轨字段：`trailEnabled`（是否启用，默认 `true`）、`trailColor`（6 位十六进制颜色，统一大写存储，默认 `#679EFE`）、`trailSpeed`（`slow` / `normal` / `fast`，默认 `slow`）、`trailWidth`（`thin` / `normal` / `thick`，默认 `thin`）。这四个字段属纯外观配置，只落盘、不进入 system prompt、不触发会话注入。\n\n字段长度上限：昵称 / 职业 50 字符，介绍 500 字符，自定义指令 2000 字符；颜色必须为 `#rrggbb` 形式。未知字段会被丢弃，非法或超限字段整单拒绝（HTTP 返回 400 与字段级错误明细）。\n\n## 实现原理\n\n「保存后下一次请求即生效」由**两条通道**共同保证（缺一不可，见 `DEBUGGING.md` 3.5）。\n\n**通道一：system prompt section。** 插件把配置编译成 system prompt 并注册到 DSH：\n\n```js\nspCtx.systemPrompt.section({\n  name: 'soul:persona',\n  order: 0,\n  // 关闭宿主提示词插值：默认开启时，用户自定义指令里任何一对完整的 {{…}}\n  // 都会让装配抛错（该抛错在 agent.step() 开头且无 try/catch ⇒ 每轮都失败）\n  interpolate: false,\n  text: () => compilePrompt(configCache || DEFAULT_CONFIG)\n})\n```\n\n宿主在**每一个 step 之前**都会重新装配提示词，对函数式 `text` provider **不做缓存**，并在文本变化时自行提交新的 system 快照 —— 所以这一条的更新时机是「下一次请求」。\n\n**通道二：活动会话注入。** 配置变化后，插件遍历所有活动 Agent，用标准 `UserMessage` 调用 `agent.inject()`：\n\n```js\nagent.inject(createUserMessage({\n  content: [{ type: 'text', text: `[dsh-soul 个性化配置已更新]\\n…\\n${prompt}` }],\n  // 会话格式 v4 要求生产者自持 kind（不得再用共享的 kind:'plugin' + plugin 字段，\n  // 那会让每一轮在 step 开始前失败）；构造见 lib/injection.mjs\n  source: { kind: 'plugin:dsh-soul', form: 'snapshot', sections: [{ name: 'soul:persona', text: prompt }] }\n}))\n```\n\n`agent.inject()` 会把最新配置放入 Agent 的待处理上下文，在下一次请求中生效；不会主动触发新请求，也不会修改历史消息。它同时是「即时生效」的可见载体：会话里会出现一条 `[dsh-soul 个性化配置已更新]` 消息。\n\n> 为什么两条都要：**只保留通道一时，实测「会话进行中修改人设」不会在下一轮生效**（0.7.1 开发中曾据此删除通道二，随后原样撤回）。`npm run verify:host` 与 `npm run verify:e2e` 分别把两条通道钉住，DSH 升级后请重跑。\n\n**诊断。** 这两条通道静默失效时症状都是「改了配置不生效」，因此插件会如实记录送达结果：`/soul show` 末尾的「送达」行、`GET /api/soul/status`、以及设置页的提示条（`configError` = 配置读不出来，`deliveryWarning` = 配置送不到活动会话）。\n\n## 许可证\n\nMIT License，完整文本见 [LICENSE](LICENSE)。\n"
    },
    {
      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-soul\",\n  \"version\": \"0.9.0\",\n  \"description\": \"为 DeepSeek Harness 添加个性化设置。\",\n  \"icon\": \"./assets/icon.svg\",\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"dsh-soul\",\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"personalization\",\n    \"persona\",\n    \"system-prompt\",\n    \"ai-assistant\",\n    \"customization\"\n  ],\n  \"type\": \"module\",\n  \"main\": \"index.mjs\",\n  \"scripts\": {\n    \"verify\": \"node scripts/verify-config.mjs && node scripts/verify-store.mjs && node scripts/verify-history.mjs && node scripts/verify-bindings.mjs && node scripts/verify-scope.mjs && node scripts/verify-session-scope.mjs && node scripts/verify-client.mjs && node scripts/verify-e2e-prompt.mjs && node scripts/verify-live-prompt.mjs && node scripts/verify-compat.mjs && node scripts/verify-trail.mjs && node scripts/verify-nav-icon.mjs\",\n    \"verify:strict\": \"node scripts/verify-config.mjs --strict && node scripts/verify-store.mjs --strict && node scripts/verify-history.mjs --strict && node scripts/verify-bindings.mjs --strict && node scripts/verify-scope.mjs --strict && node scripts/verify-session-scope.mjs --strict && node scripts/verify-client.mjs --strict && node scripts/verify-e2e-prompt.mjs --strict && node scripts/verify-live-prompt.mjs --strict && node scripts/verify-compat.mjs --strict && node scripts/verify-trail.mjs --strict && node scripts/verify-nav-icon.mjs --strict\",\n    \"verify:config\": \"node scripts/verify-config.mjs\",\n    \"verify:store\": \"node scripts/verify-store.mjs\",\n    \"verify:history\": \"node scripts/verify-history.mjs\",\n    \"verify:bindings\": \"node scripts/verify-bindings.mjs\",\n    \"verify:client\": \"node scripts/verify-client.mjs\",\n    \"verify:e2e\": \"node scripts/verify-e2e-prompt.mjs\",\n    \"verify:host\": \"node scripts/verify-live-prompt.mjs\",\n    \"verify:compat\": \"node scripts/verify-compat.mjs\",\n    \"verify:trail\": \"node scripts/verify-trail.mjs\",\n    \"verify:nav-icon\": \"node scripts/verify-nav-icon.mjs\",\n    \"verify:scope\": \"node scripts/verify-scope.mjs\",\n    \"verify:session-scope\": \"node scripts/verify-session-scope.mjs\"\n  },\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Aliuyanfeng/dsh-soul.git\"\n  },\n  \"homepage\": \"https://github.com/Aliuyanfeng/dsh-soul#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/Aliuyanfeng/dsh-soul/issues\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1 || ^4.0.5-alpha.1\",\n    \"@deepseek-ai/dsh-llm\": \">=0.1.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-tools\": \">=0.1.0-rc.6 <0.3.0-0\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-conversation\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"exports\": {\n    \".\": {\n      \"default\": \"./index.mjs\"\n    },\n    \"./client\": \"./client/index.mjs\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"index.mjs\",\n    \"lib\",\n    \"client\",\n    \"assets\",\n    \"locale\",\n    \"cordis.patch.yml\",\n    \"scripts\",\n    \"README.md\",\n    \"README_EN.md\"\n  ]\n}\n"
    },
